// Generated by `node scripts/photo-import.cjs publish <recipeId>` — do not edit by hand.
// An entry exists only for an image a human approved (docs/ai-ops/photos/manifest.json: imageStatus "approved",
// commercial-use terms checked). The recipe itself still needs editorial status "published" to be shown online.
export type RecipePhotoAsset = {
  base: string;
  widths: number[];
  width: number;
  height: number;
  alt: string;
  aiGenerated: boolean;
};

export const recipePhotos: Record<string, RecipePhotoAsset> = {};
